namespace TUnit.Mutation.Driver.Runtime;

/// Source emitted into the mutated under-test assembly. Owns the switch (env var → active set)
/// and per-test coverage capture into an AsyncLocal&lt;HashSet&lt;int&gt;&gt;.
public static class MutationRuntimeSource
{
    public const string FileName = "__TUnitMutation.Runtime.g.cs";

    public const string Code = """
        // <auto-generated />
        #nullable enable
        namespace TUnit.Mutation.Generated
        {
            using System;
            using System.Collections.Generic;
            using System.IO;
            using System.Linq;
            using System.Runtime.CompilerServices;
            using System.Text;
            using System.Threading;

            public static class MutationRuntime
            {
                // Mutable so the warm pool can swap the active set between batches via SetActive.
                // Lock-free read via Volatile so the hot IsActive path stays cheap.
                private static HashSet<int> _active;
                private static readonly bool _coverageMode;
                private static readonly string? _coverageFile;
                private static readonly object _fileLock = new();
                private static readonly object _hitsLock = new();
                private static HashSet<int>? _currentTestHits;

                static MutationRuntime()
                {
                    var active = Environment.GetEnvironmentVariable("MUTATION_ACTIVE");
                    _active = string.IsNullOrEmpty(active)
                        ? new HashSet<int>()
                        : new HashSet<int>(active.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(int.Parse));
                    _coverageMode = Environment.GetEnvironmentVariable("MUTATION_COVERAGE") == "1";
                    _coverageFile = Environment.GetEnvironmentVariable("MUTATION_COVERAGE_FILE");
                }

                /// Replaces the active-mutant set. Called by the warm-pool hook between batches.
                /// CSV format ("1,5,7"); empty/null clears.
                public static void SetActive(string? csv)
                {
                    HashSet<int> next = string.IsNullOrEmpty(csv)
                        ? new HashSet<int>()
                        : new HashSet<int>(csv.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(int.Parse));
                    Volatile.Write(ref _active, next);
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                public static bool IsActive(int id)
                {
                    if (_coverageMode)
                    {
                        lock (_hitsLock)
                        {
                            _currentTestHits?.Add(id);
                        }
                    }
                    return Volatile.Read(ref _active).Contains(id);
                }

                public static void BeginTest()
                {
                    if (!_coverageMode) return;
                    lock (_hitsLock) _currentTestHits = new HashSet<int>();
                }

                // Used by the rewriter when an assignment / increment expression at statement
                // position is wrapped in a ConditionalExpression (which is not a valid expression
                // statement). The invocation `MutationRuntime.Discard(cond ? a : b);` IS a valid
                // expression statement and evaluates the ternary for its side effects.
                public static void Discard<T>(T value) { }

                public static void EndTest(string testId, string treePath)
                {
                    if (!_coverageMode || _coverageFile is null) return;
                    HashSet<int>? hits;
                    lock (_hitsLock) { hits = _currentTestHits; _currentTestHits = null; }
                    if (hits is null || hits.Count == 0) return;
                    var sb = new StringBuilder();
                    sb.Append("{\"test\":");
                    AppendJsonString(sb, testId);
                    sb.Append(",\"path\":");
                    AppendJsonString(sb, treePath);
                    sb.Append(",\"ids\":[");
                    var first = true;
                    foreach (var id in hits)
                    {
                        if (!first) sb.Append(',');
                        sb.Append(id);
                        first = false;
                    }
                    sb.Append("]}");
                    sb.Append(Environment.NewLine);
                    lock (_fileLock) File.AppendAllText(_coverageFile, sb.ToString());
                }

                private static void AppendJsonString(StringBuilder sb, string s)
                {
                    sb.Append('"');
                    foreach (var c in s)
                    {
                        switch (c)
                        {
                            case '\\': sb.Append("\\\\"); break;
                            case '"':  sb.Append("\\\""); break;
                            case '\n': sb.Append("\\n");  break;
                            case '\r': sb.Append("\\r");  break;
                            case '\t': sb.Append("\\t");  break;
                            default:
                                if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                                else sb.Append(c);
                                break;
                        }
                    }
                    sb.Append('"');
                }
            }
        }
        """;
}
